function free_admin_html($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function free_admin_selected($a,$b) { return (string)$a === (string)$b ? 'selected' : ''; }
function free_admin_checked($value) { return !empty($value) ? 'checked' : ''; }
function free_admin_badge($status) { $class=$status==='published'?'success':($status==='archived'?'warning':'secondary'); return '<span class="free-learning-status '.$class.'">'.free_admin_html(ucfirst($status ?: 'draft')).'</span>'; }
function free_admin_thumb($path,$base) { $path=trim((string)$path); return $path !== '' && !str_contains($path,'..') ? rtrim((string)$base,'/').'/'.ltrim($path,'/') : ''; }
