(function(){
 var base=<?=json_encode(rtrim((string)$baseUrl,'/'))?>, csrf=<?=json_encode($csrf)?>, search=<?=json_encode($searchEndpoint)?>;
 document.querySelectorAll('[data-thumb-upload]').forEach(function(input){input.addEventListener('change',function(){var f=input.files&&input.files[0], box=input.closest('.free-learning-grid').querySelector('[data-thumb-preview]'); if(!f||!box)return; var r=new FileReader();r.onload=function(e){box.innerHTML='<img src="'+e.target.result+'" alt="Thumbnail preview">';};r.readAsDataURL(f);});});
 document.querySelectorAll('[data-thumb-existing]').forEach(function(select){select.addEventListener('change',function(){var box=select.closest('.free-learning-grid').querySelector('[data-thumb-preview]'), path=select.value;if(!box)return;box.innerHTML=path?'<img src='+JSON.stringify(base+'/'+path.replace(/^\/+/,''))+' alt="Thumbnail preview">':'<span class="fas fa-image" aria-hidden="true"></span><small>No thumbnail selected</small>';});});
 document.querySelectorAll('[data-relation]').forEach(function(box, relationIndex){
  var input=box.querySelector('[data-relation-search]'), hidden=box.querySelector('[data-relation-id]'), results=box.querySelector('[data-relation-results]'), timer, activeIndex=-1;
  var resultId='free-learning-relation-results-'+relationIndex;
  results.id=resultId; results.setAttribute('role','listbox'); input.setAttribute('aria-controls',resultId); input.setAttribute('aria-expanded','false');
  function options(){return Array.from(results.querySelectorAll('[role="option"]'));}
  function closeResults(){results.innerHTML=''; activeIndex=-1; input.removeAttribute('aria-activedescendant'); input.setAttribute('aria-expanded','false');}
  function setActive(index){var items=options(); if(!items.length)return; activeIndex=(index+items.length)%items.length; items.forEach(function(item,itemIndex){var active=itemIndex===activeIndex; item.classList.toggle('is-active',active); item.setAttribute('aria-selected',active?'true':'false');}); input.setAttribute('aria-activedescendant',items[activeIndex].id);}
  function choose(item){if(!item)return; input.value=item.dataset.title||item.textContent||''; hidden.value=item.dataset.resourceId||''; closeResults();}
  input.addEventListener('input',function(){clearTimeout(timer); var q=input.value.trim(); hidden.value=''; closeResults(); if(q.length<2)return; timer=setTimeout(function(){fetch(search+'?q='+encodeURIComponent(q),{credentials:'same-origin'}).then(function(response){return response.ok?response.json():{results:[]};}).then(function(data){var items=data.results||[]; results.innerHTML=''; activeIndex=-1; items.forEach(function(item,itemIndex){var button=document.createElement('button'); button.type='button'; button.id=resultId+'-option-'+itemIndex; button.setAttribute('role','option'); button.setAttribute('aria-selected','false'); button.dataset.title=item.title||''; button.dataset.resourceId=item.resource_id||''; button.textContent=(item.title||'Untitled resource')+' · '+(item.resource_type||'Resource'); button.addEventListener('click',function(){choose(button);}); results.appendChild(button);}); input.setAttribute('aria-expanded',items.length?'true':'false');}).catch(function(){closeResults();});},180);});
  input.addEventListener('keydown',function(event){var items=options(); if(event.key==='ArrowDown'&&items.length){event.preventDefault();setActive(activeIndex+1);}else if(event.key==='ArrowUp'&&items.length){event.preventDefault();setActive(activeIndex-1);}else if(event.key==='Enter'&&activeIndex>=0&&items[activeIndex]){event.preventDefault();choose(items[activeIndex]);}else if(event.key==='Escape'){closeResults();}});
  input.addEventListener('blur',function(){setTimeout(function(){if(!box.contains(document.activeElement))closeResults();},120);});
 });
 var list=document.querySelector('[data-collection-list]'), dragged=null; if(list){list.addEventListener('dragstart',function(e){dragged=e.target.closest('[data-collection-id]');if(dragged)e.dataTransfer.effectAllowed='move';});list.addEventListener('dragover',function(e){e.preventDefault();var t=e.target.closest('[data-collection-id]');if(dragged&&t&&t!==dragged){var rect=t.getBoundingClientRect();t.parentNode.insertBefore(dragged,e.clientY<rect.top+rect.height/2?t:t.nextSibling);}});list.addEventListener('drop',function(e){e.preventDefault();var ids=Array.from(list.querySelectorAll('[data-collection-id]')).map(function(x){return x.dataset.collectionId;});var body=new URLSearchParams();body.set('csrf_token',csrf);ids.forEach(function(id){body.append('collection_ids[]',id);});fetch(base+'/admin/requests/free-learning/reorder-collections',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body.toString()});});}
})();
</script></body></html>
